// 1. Kiểm tra Status Code theo dữ liệu nạp từ file JSON
const expectedStatus = pm.iterationData.get("expected_status") || 200;
const tcId = pm.iterationData.get("tc_id") || "MANUAL";

pm.test(`[${tcId}] Status code is ${expectedStatus}`, function () {
    pm.response.to.have.status(expectedStatus);
});

// 2. Kiểm tra bắt buộc sự tồn tại của Header X-Student-Id
pm.test(`[${tcId}] Request carried Header X-Student-Id`, function () {
    pm.expect(pm.request.headers.get("X-Student-Id")).to.exist;
});

// 3. Schema Validation cho kịch bản thành công (200 OK)
if (pm.response.code === 200 && pm.iterationData.get("check_schema") === true) {
    const productSchema = {
        "type": "object",
        "required": ["id", "name", "price", "description", "imageUrl", "category_id"],
        "properties": {
            "id": { "type": "number" },
            "name": { "type": "string" },
            "price": { "type": "number", "minimum": 0 },
            "description": { "type": "string" },
            "imageUrl": { "type": "string" },
            "category_id": { "type": "number" }
        }
    };

    pm.test(`[${tcId}] JSON Schema matches API Spec strictly`, function () {
        pm.response.to.have.jsonSchema(productSchema);
    });
}
